// Derive "best" badges programmatically from the data above -- never
// hardcode which model "wins" independently of the numbers.
function bestBy(metric) {
  return modelResults.reduce((best, row) => (row[metric] > best[metric] ? row : best), modelResults[0])
}

export const bestAccuracyModel = bestBy('accuracy')
export const bestF1Model = bestBy('f1')
